package com.mich.autoclipsync;
import android.app.*;import android.os.*;import android.content.*;import android.content.ClipboardManager;import android.content.ClipData;import android.widget.*;import android.view.*;import android.graphics.Typeface;
public class MainActivity extends Activity{ EditText edit; TextView status; protected void onCreate(Bundle b){super.onCreate(b); startSvc(); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(24,24,24,24); TextView title=new TextView(this); title.setText("MichAutoClipSync"); title.setTextSize(22); title.setTypeface(Typeface.DEFAULT_BOLD); root.addView(title); status=new TextView(this); status.setText("Windows tray + Android bridge. Copy field tests Android to Windows through Android clipboard observation."); root.addView(status); edit=new EditText(this); edit.setTextSize(18); edit.setSingleLine(false); edit.setMinLines(3); edit.setMaxLines(6); edit.setHint("Type/paste text here, then tap Copy field."); root.addView(edit,new LinearLayout.LayoutParams(-1,-2)); LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL); Button copy=new Button(this); copy.setText("Copy field"); copy.setOnClickListener(v->copyField()); Button paste=new Button(this); paste.setText("Paste clipboard"); paste.setOnClickListener(v->pasteField()); row.addView(copy,new LinearLayout.LayoutParams(0,-2,1)); row.addView(paste,new LinearLayout.LayoutParams(0,-2,1)); root.addView(row); setContentView(root); String seed=getIntent()==null?null:getIntent().getStringExtra("seed_text"); if(seed!=null) edit.setText(seed); // Do not request focus automatically: keeping the soft keyboard closed makes the Copy/Paste buttons visible for automated verification.
 }
protected void onNewIntent(Intent i){super.onNewIntent(i); if(i!=null&&i.hasExtra("seed_text")&&edit!=null) edit.setText(i.getStringExtra("seed_text"));}
void startSvc(){Intent i=new Intent(this,ClipBridgeService.class); if(Build.VERSION.SDK_INT>=26)startForegroundService(i); else startService(i);} void copyField(){String s=edit.getText().toString(); ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE); cm.setPrimaryClip(ClipData.newPlainText("MichAutoClipSync",s)); status.setText("Copied "+s.length()+" chars to Android clipboard; bridge observes event.");} void pasteField(){try{ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE); if(cm.hasPrimaryClip()&&cm.getPrimaryClip()!=null&&cm.getPrimaryClip().getItemCount()>0){CharSequence cs=cm.getPrimaryClip().getItemAt(0).coerceToText(this); edit.setText(cs==null?"":cs.toString());}}catch(Throwable t){status.setText("Paste failed: "+t.getClass().getSimpleName());}}}
